steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        teams(name: \"Web\") {
          nodes {
            id
            name
            issues(filter: { search: { _and: [{ title: { contains: \"login timeout\" } }] } }) {
              nodes {
                id
                title
                priority
                createdAt
                createdBy {
                  name
                }
              }
            }
          }
        }
        users {
          nodes {
            id
            name
            filter: { name: { contains: \"Maya Chen\" } }
          }
        }
      }
    "
  }'
